        return sum(x - min_val for x in nums)

class Solution {
public:
    int minMoves(vector<int>& nums) {
        int minVal = nums[0];
        for (int x : nums) if (x < minVal) minVal = x;
        long long moves = 0;
        for (int x : nums) moves += x - minVal;
        return (int)moves;
    }
};

class Solution {
    public int minMoves(int[] nums) {
        int minVal = nums[0];
        for (int x : nums) if (x < minVal) minVal = x;
        int moves = 0;
        for (int x : nums) moves += x - minVal;
        return moves;
    }
}

var minMoves = function(nums) {
    let minVal = nums[0];
    for (const x of nums) if (x < minVal) minVal = x;
    let moves = 0;
    for (const x of nums) moves += x - minVal;
    return moves;
};
